+
+// sharedTrivia is an immutable minutiae, and a single element list holding it, shared by every token whose
+// trivia is exactly that minutiae. Green nodes are never mutated after creation, so sharing them is safe.
+type sharedTrivia struct {
+	minutiae *st.STMinutiae
+	list     st.STNode
+}
+
+const (
+	maxSharedSpaces = 16
+	newlineText     = "\n"
+)
+
+var (
+	sharedSpaces  = newSharedSpaces()
+	sharedNewline = newSharedTrivia(st.END_OF_LINE_MINUTIAE, newlineText)
+)
+
+func newSharedTrivia(kind st.SyntaxKind, text string) sharedTrivia {
+	minutiae := st.CreateMinutiae(kind, text)
+	return sharedTrivia{minutiae: minutiae, list: st.CreateNodeList(minutiae)}
+}
+
+func newSharedSpaces() [maxSharedSpaces + 1]sharedTrivia {
+	var spaces [maxSharedSpaces + 1]sharedTrivia
+	for i := 1; i <= maxSharedSpaces; i++ {
+		spaces[i] = newSharedTrivia(st.WHITESPACE_MINUTIAE, strings.Repeat(" ", i))
+	}
+	return spaces
+}
+
+func whitespaceMinutiae(text string) st.STNode {
+	if len(text) <= maxSharedSpaces && isOnlySpaces(text) {
+		return sharedSpaces[len(text)].minutiae
+	}
+	return st.CreateMinutiae(st.WHITESPACE_MINUTIAE, text)
+}
+
+func endOfLineMinutiae(text string) st.STNode {
+	if text == newlineText {
+		return sharedNewline.minutiae
+	}
+	return st.CreateMinutiae(st.END_OF_LINE_MINUTIAE, text)
+}
+
+func isOnlySpaces(text string) bool {
+	if text == "" {
+		return false
+	}
+	for i := 0; i < len(text); i++ {
+		if text[i] != ' ' {
+			return false
+		}
+	}
+	return true
+}
+
+// sharedTriviaList returns the shared list for trivia if it consists of exactly one shared minutiae.
+func sharedTriviaList(trivia []st.STNode) (st.STNode, bool) {
+	if len(trivia) != 1 {
+		return nil, false
+	}
+	m, ok := trivia[0].(*st.STMinutiae)
+	if !ok {
+		return nil, false
+	}
+	if m == sharedNewline.minutiae {
+		return sharedNewline.list, true
+	}
+	width := int(m.Width())
+	if width <= maxSharedSpaces && m == sharedSpaces[width].minutiae {
+		return sharedSpaces[width].list, true
+	}
+	return nil, false
+}
+
+// takeTriviaList creates a node list from the collected trivia and resets the reusable buffer.
+func takeTriviaList(triviaList *[]st.STNode) st.STNode {
+	if len(*triviaList) == 0 {
+		return st.CreateEmptyNodeList()
+	}
+	trivia, ok := sharedTriviaList(*triviaList)
+	if !ok {
+		trivia = st.CreateNodeList(slices.Clone(*triviaList)...)
+	}
+	clear(*triviaList)
+	*triviaList = (*triviaList)[:0]
+	return trivia
 }

